package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check for insecure protocol strings in variables (Ansible vars files)
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Check if variable value contains http:// (cleartext)
    insecure_protocol := "http://"
    check_value_for_insecure_protocol(var.value, insecure_protocol)

    result := {
        "type": "sec_https",
        "element": var,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Using unencrypted protocol (http) for sensitive data transmission. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check for insecure protocol strings in attributes (Ansible tasks, Chef resources)
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check if attribute name is "validate_certs" and value is "no"
    attr.name == "validate_certs"
    attr.value.ir_type == "String"
    attr.value.value == "no"

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Certificate validation disabled, allowing insecure connections. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check for insecure protocol strings in attributes (Chef remote_file source)
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check if attribute name is "source" and contains http://
    attr.name == "source"
    check_value_for_insecure_protocol(attr.value, "http://")

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Using unencrypted protocol (http) for file source. (CWE-319)"
    }
}

# Helper function to recursively check values for insecure protocols
check_value_for_insecure_protocol(value, protocol) {
    value.ir_type == "String"
    contains(value.value, protocol)
} else {
    value.ir_type == "Sum"
    check_value_for_insecure_protocol(value.left, protocol)
} else {
    value.ir_type == "Sum"
    check_value_for_insecure_protocol(value.right, protocol)
} else {
    value.ir_type == "Hash"
    check_hash_for_insecure_protocol(value.value, protocol)
} else {
    value.ir_type == "Array"
    check_array_for_insecure_protocol(value.value, protocol)
}

check_hash_for_insecure_protocol(hash_pairs, protocol) {
    pair := hash_pairs[_]
    check_value_for_insecure_protocol(pair.value, protocol)
}

check_array_for_insecure_protocol(array_items, protocol) {
    item := array_items[_]
    check_value_for_insecure_protocol(item, protocol)
}

